(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB1LC_1LA1RD_1RD1LA_0LC0RB : forall j, lift (cden [] [] j BB1_1RB1LC_1LA1RD_1RD1LA_0LC0RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LC_1LA1RD_1RD1LA_0LC0RB = (StD, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold cden, BB1_1RB1LC_1LA1RD_1RD1LA_0LC0RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB1LC_1LA1RD_1RD1LA_0LC0RB. rewrite epow2_1RB1LC_1LA1RD_1RD1LA_0LC0RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LC_1LA1RD_1RD1LA_0LC0RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LC_1LA1RD_1RD1LA_0LC0RB : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LC_1LA1RD_1RD1LA_0LC0RB.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LC_1LA1RD_1RD1LA_0LC0RB, cden, BE0_1RB1LC_1LA1RD_1RD1LA_0LC0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LC_1LA1RD_1RD1LA_0LC0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1LC_1LA1RD_1RD1LA_0LC0RB p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LC_1LA1RD_1RD1LA_0LC0RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LC_1LA1RD_1RD1LA_0LC0RB p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LC_1LA1RD_1RD1LA_0LC0RB).
    split; [lia|]. split; [| exact (gbo_1RB1LC_1LA1RD_1RD1LA_0LC0RB j)].
    rewrite (gso_1RB1LC_1LA1RD_1RD1LA_0LC0RB p j E).
    exact (srun_sound tm true true chb_1RB1LC_1LA1RD_1RD1LA_0LC0RB B0_1RB1LC_1LA1RD_1RD1LA_0LC0RB BB1_1RB1LC_1LA1RD_1RD1LA_0LC0RB 4 4
             run_boot_1RB1LC_1LA1RD_1RD1LA_0LC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 6), (cden [] [] j B1_1RB1LC_1LA1RD_1RD1LA_0LC0RB).
    split; [| exact (geo_1RB1LC_1LA1RD_1RD1LA_0LC0RB p j E)].
    rewrite (gxi_1RB1LC_1LA1RD_1RD1LA_0LC0RB j).
    exact (srun_sound tm true true che_1RB1LC_1LA1RD_1RD1LA_0LC0RB BE0_1RB1LC_1LA1RD_1RD1LA_0LC0RB B1_1RB1LC_1LA1RD_1RD1LA_0LC0RB 4 6
             run_exit_1RB1LC_1LA1RD_1RD1LA_0LC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LC_1LA1RD_1RD1LA_0LC0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LC_1LA1RD_1RD1LA_0LC0RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LC_1LA1RD_1RD1LA_0LC0RB p j' E).
Qed.

